<article id={msgId} class="border border-gray-700 rounded-lg overflow-hidden scroll-mt-4 transition-colors duration-500">
  <!-- Header -->
  <header
    class="group px-4 py-2 font-semibold border-b border-gray-700 flex items-center justify-between cursor-pointer"
    class:bg-role-system={role === 'system'}
    class:bg-role-developer={role === 'developer'}
    class:bg-role-user={role === 'user'}
    class:bg-role-assistant={role === 'assistant'}
    class:bg-role-tool={role === 'tool'}
    style="--tw-bg-opacity: 0.2"
    onclick={() => copy(msgId)}
  >
    <span class="text-{colorClass}">{index}: {displayRole}</span>
    <LinkButton id={msgId} />
  </header>

  <!-- Content -->
  <div class="p-4 bg-gray-800/50">
    {#if role === 'tool'}
      <ToolResult {content} msgIndex={index} durationMs={message.duration_ms} />
    {:else}
      <!-- Reasoning (for assistant messages with extended thinking) -->
      {#if reasoning}
        <div class="mb-4 pl-4 border-l-2 border-gray-600 text-gray-400 italic whitespace-pre-wrap">
          {reasoning}
        </div>
      {/if}

      <!-- Main content -->
      {#if content}
        {#if isSemanticGrepMatches}
          <SemanticGrepMatches {content} />
        {:else if shouldRenderMarkdown}
          <!-- Markdown content with toggle -->
          <div class="space-y-2">
            <div class="flex items-center gap-2 text-sm">
              <button
                class="px-2 py-1 rounded {showRaw ? 'bg-gray-600 text-white' : 'bg-gray-800 text-gray-400'}"
                onclick={() => (showRaw = true)}
              >
                Raw
              </button>
              <button
                class="px-2 py-1 rounded {showRaw ? 'bg-gray-800 text-gray-400' : 'bg-gray-600 text-white'}"
                onclick={() => (showRaw = false)}
              >
                Markdown
              </button>
            </div>
            {#if showRaw}
              <div class="whitespace-pre-wrap text-gray-200">
                {content}
              </div>
            {:else}
              <Markdown {content} />
            {/if}
          </div>
        {:else}
          <div class="whitespace-pre-wrap text-gray-200">
            {content}
          </div>
        {/if}
      {/if}


      <!-- Timings (assistant) -->
      {#if role === 'assistant' && timingsDisplay}
        <div class="mb-3 text-xs text-gray-400 font-mono">{timingsDisplay}</div>
      {/if}
      <!-- Tool calls (for assistant) -->
      {#if toolCalls && toolCalls.length > 0}
